import React from 'react';
import * as THREE from 'three';
import { Stage, cyl } from '../Stage';

// Detailed animated water via a custom GLSL ShaderMaterial, tuned to RCT2's
// bright park water. Six directional wave octaves displace the mesh; the
// fragment stage adds high-frequency procedural ripple normals, crest foam,
// an edge foam ring near the shore (uRadius), depth colour gradient, Fresnel
// rim, sun specular and glints. `radius` clips to a round pool; pass a huge
// radius for a square sheet (TerrainMap).
export function buildWater(t: typeof THREE, size = 4, seg = 140, radius = 1e6) {
  const geo = new t.PlaneGeometry(size, size, seg, seg);
  const mat = new t.ShaderMaterial({
    transparent: true,
    depthWrite: true,
    uniforms: {
      uTime: { value: 0 },
      uRadius: { value: radius },
      uShallow: { value: new t.Color(0x63d0e8) },
      uMid: { value: new t.Color(0x2286c8) },
      uDeep: { value: new t.Color(0x0c3a70) },
      uSun: { value: new t.Vector3(6, 11, 5).normalize() },
    },
    vertexShader: [
      'uniform float uTime;',
      'varying float vH;',
      'varying vec3 vWorld;',
      'varying vec2 vLocal;',
      'float wave(vec2 p, vec2 dir, float freq, float speed, float amp, float tme) {',
      '  return sin(dot(p, dir) * freq + tme * speed) * amp;',
      '}',
      'void main() {',
      '  vLocal = position.xy;',
      '  vec3 p = position;',
      '  float tme = uTime;',
      '  float w = 0.0;',
      '  w += wave(p.xy, vec2(1.0, 0.2), 1.1, 1.3, 0.10, tme);',
      '  w += wave(p.xy, vec2(-0.4, 1.0), 1.7, 1.7, 0.07, tme);',
      '  w += wave(p.xy, vec2(0.8, 0.8), 0.8, 1.05, 0.065, tme);',
      '  w += wave(p.xy, vec2(-0.9, 0.5), 2.3, 2.1, 0.035, tme);',
      '  w += wave(p.xy, vec2(0.3, -1.0), 3.1, 2.6, 0.022, tme);',
      '  w += wave(p.xy, vec2(-0.7, -0.7), 4.3, 3.2, 0.012, tme);',
      '  p.z += w;',
      '  vH = w;',
      '  vec4 wp = modelMatrix * vec4(p, 1.0);',
      '  vWorld = wp.xyz;',
      '  gl_Position = projectionMatrix * viewMatrix * wp;',
      '}',
    ].join('\n'),
    fragmentShader: [
      'precision highp float;',
      'uniform float uTime;',
      'uniform float uRadius;',
      'uniform vec3 uShallow;',
      'uniform vec3 uMid;',
      'uniform vec3 uDeep;',
      'uniform vec3 uSun;',
      'varying float vH;',
      'varying vec3 vWorld;',
      'varying vec2 vLocal;',
      'float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }',
      'void main() {',
      '  float r = length(vLocal);',
      '  if (r > uRadius) discard;',
      '  vec3 n = normalize(cross(dFdx(vWorld), dFdy(vWorld)));',
      // high-frequency procedural ripple detail layered onto the geometric normal
      '  float rip = sin(vWorld.x * 34.0 + uTime * 3.1) * sin(vWorld.z * 29.0 - uTime * 2.6)',
      '            + 0.6 * sin(vWorld.x * 61.0 - uTime * 4.4) * sin(vWorld.z * 53.0 + uTime * 3.7);',
      '  n = normalize(n + vec3(dFdx(rip), 0.0, dFdy(rip)) * 6.0);',
      '  vec3 v = normalize(cameraPosition - vWorld);',
      '  float fres = pow(1.0 - max(dot(n, v), 0.0), 3.0);',
      // three-stop depth gradient driven by wave height
      '  float hMix = clamp(vH * 3.2 + 0.5, 0.0, 1.0);',
      '  vec3 base = hMix < 0.5 ? mix(uDeep, uMid, hMix * 2.0) : mix(uMid, uShallow, hMix * 2.0 - 1.0);',
      '  vec3 l = normalize(uSun);',
      '  vec3 hf = normalize(l + v);',
      '  float spec = pow(max(dot(n, hf), 0.0), 90.0);',
      '  float diff = max(dot(n, l), 0.0) * 0.45 + 0.55;',
      '  vec3 col = base * diff + vec3(1.0) * spec * 0.85 + fres * vec3(0.55, 0.78, 1.0) * 0.45;',
      // crest foam: bright broken streaks on the highest wave tops
      '  float crest = smoothstep(0.16, 0.24, vH);',
      '  float streak = hash(floor(vWorld.xz * 14.0) + floor(uTime * 2.0));',
      '  col = mix(col, vec3(0.92, 0.97, 1.0), crest * streak * 0.7);',
      // shore foam ring hugging the pool edge (only when a real radius is set)
      '  if (uRadius < 1000.0) {',
      '    float shore = smoothstep(uRadius - 0.22, uRadius - 0.03, r);',
      '    float lap = 0.5 + 0.5 * sin(r * 26.0 - uTime * 2.4 + rip * 2.0);',
      '    col = mix(col, vec3(0.94, 0.98, 1.0), shore * (0.45 + 0.45 * lap));',
      '  }',
      // sun glints
      '  float sp = sin(vWorld.x * 24.0 + uTime * 6.0) * sin(vWorld.z * 24.0 - uTime * 5.0);',
      '  col += smoothstep(0.94, 1.0, sp) * 0.3;',
      '  gl_FragColor = vec4(col, 0.95);',
      '}',
    ].join('\n'),
  });
  const mesh = new t.Mesh(geo, mat);
  mesh.rotation.x = -Math.PI / 2;
  return { mesh, update: (time: number) => (mat.uniforms.uTime.value = time) };
}

export function WaterTile() {
  return (
    <Stage
      distance={5}
      targetY={0.2}
      background="#bfe6f2"
      ground={false}
      build={(t, g) => {
        // opaque sand basin + dark pool floor + beach rim so nothing shows through
        g.add(cyl(t, 2.5, 2.7, 0.7, 0xcdb98a, [0, -0.35, 0], { tex: 'sand', repeat: [10, 2], rough: 1, seg: 48 }));
        g.add(cyl(t, 2.35, 2.35, 0.1, 0x0c3a70, [0, 0.02, 0], { rough: 0.35, seg: 48 }));
        g.add(cyl(t, 2.55, 2.7, 0.18, 0x9a8a5f, [0, 0.06, 0], { tex: 'sand', repeat: [12, 1], rough: 1, seg: 48 }));
        const water = buildWater(t, 4.8, 140, 2.32);
        water.mesh.position.y = 0.16;
        g.add(water.mesh);
        return (time) => water.update(time);
      }}
    />
  );
}

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Ferris wheel matched to the RCT2 FWH1 sprite: a MAGENTA/PINK spoked wheel
// with lattice cross-bracing between paired rings, an ORANGE outer rim band,
// dark slate-teal lattice A-frame supports, and open two-seat bench gondolas
// (dark teal) that hang inside the rim and stay upright as the wheel turns.
export function FerrisWheel() {
  return (
    <Stage
      distance={9}
      targetY={2.4}
      build={(t, g) => {
        const R = 2.4;
        const cy = 2.7;
        const PINK = 0xd6338c; // wheel spokes/rings (sprite #d03080/#e050a0)
        const ORANGE = 0xe8641c; // outer rim band (sprite #e05020/#f07020)
        const SLATE = 0x3c5454; // support lattice (sprite #305050)
        const SEAT = 0x24383a; // gondola benches

        // A-frame lattice supports (two planes), dark slate like the sprite
        for (const sx of [-1, 1])
          for (const z of [-0.5, 0.5]) {
            const x0 = sx * 1.5;
            const L = Math.hypot(x0, cy);
            const ang = Math.atan2(cy, -x0) - Math.PI / 2;
            g.add(box(t, [0.11, L, 0.11], SLATE, [x0 / 2, cy / 2, z], { tex: 'metal', repeat: [1, 6], metal: 0.4, rough: 0.6, rotZ: ang }));
            // lattice rungs up each leg
            for (let k = 1; k < 5; k++) {
              const yy = (cy * k) / 5;
              const xx = x0 * (1 - k / 5);
              g.add(box(t, [0.32, 0.05, 0.05], SLATE, [xx, yy, z], { metal: 0.4, rough: 0.6 }));
            }
          }
        // cross ties between the two support planes + footing pads
        [-1, 1].forEach((sx) => {
          g.add(box(t, [0.08, 0.08, 1.05], SLATE, [sx * 0.75, cy / 2, 0], { metal: 0.4, rough: 0.6 }));
          [-0.5, 0.5].forEach((z) => g.add(box(t, [0.5, 0.12, 0.4], 0x8a8f98, [sx * 1.5, 0.06, z], { tex: 'concrete', rough: 0.9 })));
        });
        g.add(cyl(t, 0.1, 0.1, 1.16, 0x9aa2ab, [0, cy, 0], { rotX: Math.PI / 2, tex: 'metal', metal: 0.8, rough: 0.3, seg: 16 })); // axle

        const wheel = new t.Group();
        wheel.position.set(0, cy, 0);
        g.add(wheel);

        // paired pink inner rings + ORANGE outer rim rings (slightly larger)
        for (const z of [-0.4, 0.4]) {
          const inner = new t.Mesh(new t.TorusGeometry(R * 0.82, 0.045, 8, 48), new t.MeshStandardMaterial({ color: PINK, metalness: 0.3, roughness: 0.5 }));
          inner.position.z = z;
          inner.castShadow = true;
          wheel.add(inner);
          const outer = new t.Mesh(new t.TorusGeometry(R, 0.055, 8, 48), new t.MeshStandardMaterial({ color: ORANGE, metalness: 0.3, roughness: 0.5 }));
          outer.position.z = z;
          outer.castShadow = true;
          wheel.add(outer);
        }
        // hub discs
        [-0.42, 0.42].forEach((z) => wheel.add(cyl(t, 0.16, 0.16, 0.06, 0x9aa2ab, [0, 0, z], { rotX: Math.PI / 2, metal: 0.7, rough: 0.35, seg: 18 })));

        // 16 pink spokes per plane + lattice cross-bracing between rings
        const NS = 16;
        for (let i = 0; i < NS; i++) {
          const a = (i / NS) * Math.PI * 2;
          [-0.4, 0.4].forEach((z) => {
            wheel.add(box(t, [0.035, R * 2, 0.035], PINK, [0, 0, z], { rotZ: a, metal: 0.3, rough: 0.5 }));
          });
          // radial cross-tie connecting the two planes at the rim
          wheel.add(box(t, [0.05, 0.05, 0.86], PINK, [Math.cos(a + Math.PI / 2) * R * 0.91, Math.sin(a + Math.PI / 2) * R * 0.91, 0], { metal: 0.3, rough: 0.5 }));
          // zig-zag lattice between inner and outer ring (per plane)
          [-0.4, 0.4].forEach((z) => {
            const mid = (R * 0.82 + R) / 2;
            wheel.add(box(t, [0.03, 0.42, 0.03], PINK, [Math.cos(a + Math.PI / 2 + 0.1) * mid, Math.sin(a + Math.PI / 2 + 0.1) * mid, z], { rotZ: a + 0.5, metal: 0.3, rough: 0.5 }));
          });
        }

        // 8 open bench gondolas, dark teal, hanging inside the rim, kept upright
        const N = 8;
        const gondolas: ReturnType<typeof buildPeep>['group'][] = [];
        for (let i = 0; i < N; i++) {
          const gd = new t.Group();
          gd.add(box(t, [0.46, 0.07, 0.4], SEAT, [0, -0.16, 0], { rough: 0.8 })); // bench seat
          gd.add(box(t, [0.46, 0.3, 0.06], SEAT, [0, -0.02, -0.17], { rough: 0.8 })); // seat back
          gd.add(box(t, [0.46, 0.05, 0.05], ORANGE, [0, 0.06, 0.16], { rough: 0.5 })); // safety bar
          [-0.2, 0.2].forEach((x) => gd.add(box(t, [0.04, 0.34, 0.04], SLATE, [x, 0.06, 0], { metal: 0.4, rough: 0.6 }))); // hangers
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true });
          p.group.scale.setScalar(0.36);
          p.group.position.set(0, -0.17, 0.02);
          gd.add(p.group);
          g.add(gd);
          gondolas.push(gd as never);
        }
        return (time) => {
          wheel.rotation.z = time * 0.35;
          for (let i = 0; i < N; i++) {
            const a = (i / N) * Math.PI * 2 + wheel.rotation.z;
            const gd = gondolas[i] as unknown as { position: { set: (x: number, y: number, z: number) => void }; rotation: { z: number } };
            gd.position.set(Math.cos(a) * R * 0.88, cy + Math.sin(a) * R * 0.88, 0);
            gd.rotation.z = Math.sin(time * 2 + i) * 0.06; // gentle sway, stays upright
          }
        };
      }}
    />
  );
}

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Swinging ship matched to the RCT2 SWSH1 sprite: an ORANGE A-frame (two legs
// per side meeting at a high pivot), a dark slate cross-beam and centre pole,
// and a MAGENTA hull with carved dragon heads at BOTH ends, orange gunwale
// trim and rows of orange/pink striped seat backs. Riders swing with it.
export function PirateShip() {
  return (
    <Stage
      distance={8.5}
      targetY={1.7}
      build={(t, g) => {
        const pivotY = 3.1;
        const ORANGE = 0xe8641c; // frame (sprite #e05020)
        const MAGENTA = 0xd6338c; // hull + dragons (sprite #e050a0)
        const MAG_D = 0x9c2364; // hull shadow tone
        const SLATE = 0x2e4444; // beam/pole (sprite #203030)

        // orange A-frame: two legs each side, meeting at the pivot
        [-1, 1].forEach((zs) => {
          const z = zs * 0.7;
          [-1, 1].forEach((xs) => {
            const x0 = xs * 1.6;
            const L = Math.hypot(x0, pivotY);
            const ang = Math.atan2(pivotY, -x0) - Math.PI / 2;
            g.add(box(t, [0.13, L, 0.13], ORANGE, [x0 / 2, pivotY / 2, z], { tex: 'metal', repeat: [1, 7], metal: 0.3, rough: 0.55, rotZ: ang }));
          });
          // horizontal tie between the two legs of this frame
          g.add(box(t, [1.7, 0.1, 0.1], ORANGE, [0, pivotY * 0.45, z], { metal: 0.3, rough: 0.55 }));
          // footing pads
          [-1, 1].forEach((xs) => g.add(box(t, [0.5, 0.12, 0.4], 0x8a8f98, [xs * 1.6, 0.06, z], { tex: 'concrete', rough: 0.9 })));
        });
        // slate cross-beam through the pivot + hub caps
        g.add(cyl(t, 0.09, 0.09, 1.7, SLATE, [0, pivotY, 0], { rotX: Math.PI / 2, metal: 0.5, rough: 0.4, seg: 14 }));
        [-0.72, 0.72].forEach((z) => g.add(cyl(t, 0.14, 0.14, 0.08, ORANGE, [0, pivotY, z], { rotX: Math.PI / 2, metal: 0.4, rough: 0.5, seg: 14 })));

        const swing = new t.Group();
        swing.position.set(0, pivotY, 0);
        g.add(swing);
        // dark centre pole (the sprite hangs the boat from a single slate mast)
        swing.add(box(t, [0.11, 2.5, 0.11], SLATE, [0, -1.25, 0], { metal: 0.5, rough: 0.4 }));
        // magenta counterweight drum near the pivot (visible in the sprite)
        swing.add(cyl(t, 0.24, 0.3, 0.36, MAGENTA, [0, -0.45, 0], { rough: 0.5, seg: 16 }));

        const boat = new t.Group();
        boat.position.y = -2.5;
        swing.add(boat);
        // magenta hull, layered for a curved profile, orange gunwale trim
        boat.add(box(t, [2.5, 0.34, 0.8], MAG_D, [0, -0.05, 0], { tex: 'plastic', repeat: [6, 1], rough: 0.5 }));
        boat.add(box(t, [2.7, 0.3, 0.88], MAGENTA, [0, 0.22, 0], { tex: 'plastic', repeat: [6, 1], rough: 0.5 }));
        boat.add(box(t, [2.74, 0.07, 0.92], ORANGE, [0, 0.4, 0], { rough: 0.5 })); // gunwale
        boat.add(box(t, [2.2, 0.24, 0.7], 0x1c2e2e, [0, 0.34, 0], { rough: 0.85 })); // dark interior well
        // upswept ends + dragon heads at BOTH ends
        [-1, 1].forEach((s) => {
          boat.add(box(t, [0.55, 0.6, 0.8], MAGENTA, [s * 1.35, 0.35, 0], { tex: 'plastic', repeat: [2, 2], rough: 0.5, rotZ: s * 0.55 }));
          const neck = cyl(t, 0.09, 0.14, 0.6, MAGENTA, [s * 1.72, 0.85, 0], { rough: 0.5, seg: 10, rotZ: s * 0.5 });
          boat.add(neck);
          boat.add(ball(t, 0.17, MAGENTA, [s * 1.92, 1.12, 0], { flat: true, rough: 0.5 })); // head
          boat.add(box(t, [0.2, 0.09, 0.1], MAGENTA, [s * 2.08, 1.08, 0], { rough: 0.5 })); // snout
          boat.add(ball(t, 0.035, 0x1c2e2e, [s * 1.98, 1.18, 0.09])); // eye
          boat.add(ball(t, 0.035, 0x1c2e2e, [s * 1.98, 1.18, -0.09]));
        });
        // rows of orange/pink striped seat backs + riders
        for (let i = 0; i < 6; i++) {
          const z0 = -1.0 + i * 0.4;
          boat.add(box(t, [0.06, 0.3, 0.72], i % 2 ? ORANGE : MAGENTA, [z0, 0.5, 0], { rough: 0.55 })); // seat back (across hull)
          if (i < 5) {
            const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true, expression: 'surprised' });
            p.group.scale.setScalar(0.4);
            p.group.position.set(z0 + 0.2, 0.36, 0);
            p.group.rotation.y = Math.PI / 2;
            boat.add(p.group);
          }
        }
        return (time) => {
          swing.rotation.z = Math.sin(time * 1.05) * 0.85;
        };
      }}
    />
  );
}

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SKIN_TONES } from '../Guest';

// Merry-go-round matched to the RCT2 MGR1 sprite: a flat conical canopy with
// ORANGE/WHITE pinwheel stripes and a scalloped orange rim, a green+gold
// decorated frieze band, WHITE horses with pink saddles on gold poles, a tan
// wooden deck, and stacked orange ring steps at the base.
export function Carousel() {
  return (
    <Stage
      distance={6.8}
      targetY={1.05}
      build={(t, g) => {
        const ORANGE = 0xe8641c;
        const CREAM = 0xdad4c8; // canopy white (sprite #d0d0d0)
        const TAN = 0x9a8456; // deck wood (sprite #605030 lit)
        const GREEN = 0x4c6e30; // frieze trim
        const GOLD = 0xd8b040;
        const HORSE = 0xf0ece4; // white horses
        const SADDLE = 0xd6338c; // pink saddles

        // stacked orange ring steps at the base (sprite shows 2-3 ledges)
        g.add(cyl(t, 1.78, 1.86, 0.1, ORANGE, [0, 0.05, 0], { rough: 0.7, seg: 36 }));
        g.add(cyl(t, 1.68, 1.76, 0.1, 0xc44a14, [0, 0.15, 0], { rough: 0.7, seg: 36 }));
        g.add(cyl(t, 1.6, 1.66, 0.08, ORANGE, [0, 0.24, 0], { rough: 0.7, seg: 36 }));

        const ride = new t.Group();
        g.add(ride);
        // tan wooden deck
        ride.add(cyl(t, 1.52, 1.52, 0.1, TAN, [0, 0.33, 0], { tex: 'wood', repeat: [10, 1], rough: 0.85, seg: 36 }));
        // centre drum, gold-trimmed with mirrored panels
        ride.add(cyl(t, 0.34, 0.34, 1.35, 0xb8a070, [0, 1.05, 0], { tex: 'wood', repeat: [6, 2], rough: 0.7, seg: 20 }));
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * Math.PI * 2;
          ride.add(box(t, [0.1, 0.5, 0.02], GOLD, [Math.cos(a) * 0.35, 1.05, Math.sin(a) * 0.35], { metal: 0.6, rough: 0.3, rotY: -a }));
        }

        // pinwheel canopy: alternating orange/white wedge segments (flat cone)
        const SEGS = 16;
        for (let i = 0; i < SEGS; i++) {
          const a0 = (i / SEGS) * Math.PI * 2;
          const wedge = new t.Mesh(
            new t.CylinderGeometry(0.04, 1.78, 0.5, 3, 1, false, a0, (Math.PI * 2) / SEGS),
            new t.MeshStandardMaterial({ color: i % 2 ? ORANGE : CREAM, roughness: 0.6 }),
          );
          wedge.position.y = 2.12;
          wedge.castShadow = true;
          ride.add(wedge);
        }
        // scalloped orange rim band under the canopy edge
        ride.add(cyl(t, 1.8, 1.8, 0.1, ORANGE, [0, 1.88, 0], { rough: 0.6, seg: 36 }));
        for (let i = 0; i < 18; i++) {
          const a = (i / 18) * Math.PI * 2;
          ride.add(ball(t, 0.08, ORANGE, [Math.cos(a) * 1.8, 1.82, Math.sin(a) * 1.8], { flat: true, rough: 0.6 })); // scallops
        }
        // green + gold frieze ring
        ride.add(cyl(t, 1.72, 1.72, 0.07, GREEN, [0, 1.79, 0], { rough: 0.7, seg: 36 }));
        ride.add(cyl(t, 1.74, 1.74, 0.03, GOLD, [0, 1.74, 0], { metal: 0.6, rough: 0.3, seg: 36 }));
        // finial on top
        ride.add(cyl(t, 0.02, 0.02, 0.5, GOLD, [0, 2.55, 0], { metal: 0.7, rough: 0.3, seg: 8 }));
        ride.add(ball(t, 0.09, GOLD, [0, 2.8, 0], { metal: 0.7, rough: 0.3 }));

        // 8 white horses with pink saddles on gold poles, alternating riders
        const horses: { grp: THREE.Group; ph: number }[] = [];
        const N = 8;
        for (let i = 0; i < N; i++) {
          const a = (i / N) * Math.PI * 2;
          const hg = new t.Group();
          hg.position.set(Math.cos(a) * 1.12, 0.92, Math.sin(a) * 1.12);
          hg.rotation.y = -a + Math.PI / 2;
          hg.add(cyl(t, 0.022, 0.022, 1.5, GOLD, [0, 0.3, 0], { tex: 'metal', metal: 0.85, rough: 0.2, seg: 10 }));
          // horse: body, chest, neck, head, muzzle, legs mid-gallop, tail
          hg.add(box(t, [0.48, 0.2, 0.17], HORSE, [0, 0, 0], { rough: 0.55 }));
          hg.add(ball(t, 0.11, HORSE, [0.24, 0.02, 0], { rough: 0.55 })); // chest
          hg.add(box(t, [0.13, 0.24, 0.12], HORSE, [0.27, 0.17, 0], { rough: 0.55, rotZ: -0.3 })); // neck
          hg.add(box(t, [0.18, 0.11, 0.11], HORSE, [0.37, 0.3, 0], { rough: 0.55 })); // head
          hg.add(box(t, [0.09, 0.07, 0.08], 0xd8cfc0, [0.46, 0.28, 0], { rough: 0.55 })); // muzzle
          hg.add(box(t, [0.28, 0.05, 0.02], SADDLE, [-0.02, 0.11, 0.09], { rough: 0.6 })); // saddle blanket
          hg.add(box(t, [0.28, 0.05, 0.02], SADDLE, [-0.02, 0.11, -0.09], { rough: 0.6 }));
          hg.add(box(t, [0.2, 0.05, 0.17], SADDLE, [-0.02, 0.12, 0], { rough: 0.6 })); // saddle
          // galloping legs (front pair forward, rear pair back)
          hg.add(box(t, [0.05, 0.24, 0.05], HORSE, [0.19, -0.19, 0.05], { rough: 0.55, rotZ: 0.5 }));
          hg.add(box(t, [0.05, 0.24, 0.05], HORSE, [0.19, -0.19, -0.05], { rough: 0.55, rotZ: 0.3 }));
          hg.add(box(t, [0.05, 0.24, 0.05], HORSE, [-0.19, -0.19, 0.05], { rough: 0.55, rotZ: -0.5 }));
          hg.add(box(t, [0.05, 0.24, 0.05], HORSE, [-0.19, -0.19, -0.05], { rough: 0.55, rotZ: -0.3 }));
          hg.add(box(t, [0.14, 0.05, 0.04], 0xd8cfc0, [-0.29, 0.06, 0], { rough: 0.55, rotZ: 0.5 })); // tail
          if (i % 2 === 0) {
            const p = buildPeep(t, { skin: SKIN_TONES[(i / 2) % SKIN_TONES.length], shirt: [0x3aa0e0, 0xe0a020, 0x2e9e54, 0xd6338c][(i / 2) % 4], seated: true });
            p.group.scale.setScalar(0.42);
            p.group.position.set(-0.02, 0.13, 0);
            p.group.rotation.y = -Math.PI / 2;
            hg.add(p.group);
          }
          ride.add(hg);
          horses.push({ grp: hg, ph: a });
        }
        return (time) => {
          ride.rotation.y = time * 0.55;
          horses.forEach((hh) => (hh.grp.position.y = 0.92 + Math.sin(time * 3 + hh.ph * 2) * 0.11));
        };
      }}
    />
